import { fileURLToPath } from 'node:url';
import { drizzle } from 'drizzle-orm/node-postgres';
import { migrate } from 'drizzle-orm/node-postgres/migrator';
import pg from 'pg';

/** Folder with the SQL migrations generated by drizzle-kit. */
export const migrationsFolder = fileURLToPath(new URL('../migrations', import.meta.url));

/** Arbitrary constant shared by every Crewhall process that migrates. */
const MIGRATION_LOCK_KEY = 7_412_093_551;

/**
 * Runs pending migrations under a Postgres advisory lock, so when several api
 * replicas start together only one migrates and the others wait, then see nothing to do.
 * Migrations only move forward ("expand, then contract", design doc 17 §11).
 */
export async function runMigrations(
  connectionString: string,
  options: { folder?: string } = {},
): Promise<void> {
  const client = new pg.Client({ connectionString });
  await client.connect();
  try {
    await client.query('select pg_advisory_lock($1)', [MIGRATION_LOCK_KEY]);
    try {
      await migrate(drizzle(client), { migrationsFolder: options.folder ?? migrationsFolder });
    } finally {
      await client.query('select pg_advisory_unlock($1)', [MIGRATION_LOCK_KEY]);
    }
  } finally {
    await client.end();
  }
}
